<span class="line"><span class="__shiki_140thh">  [x </span><span class="__shiki_1itgoe">IN</span><span class="__shiki_140thh"> list | x </span><span class="__shiki_1itgoe">*</span><span class="__shiki_dzsirb"> 2</span><span class="__shiki_140thh">] </span><span class="__shiki_1itgoe">as</span><span class="__shiki_140thh"> doubled</span></span>
