<span class="line"><span class="__shiki_1itgoe">UNWIND</span><span class="__shiki_140thh"> [</span><span class="__shiki_dzsirb">1</span><span class="__shiki_140thh">, </span><span class="__shiki_dzsirb">2</span><span class="__shiki_140thh">, </span><span class="__shiki_dzsirb">3</span><span class="__shiki_140thh">] </span><span class="__shiki_1itgoe">AS</span><span class="__shiki_140thh"> number</span></span>
