<span class="line"><span class="__shiki_1itgoe">MATCH</span><span class="__shiki_140thh"> (friend)</span><span class="__shiki_dzsirb">-</span><span class="__shiki_1itgoe">[:</span><span class="__shiki_1t8gfj">LIKES</span><span class="__shiki_1itgoe">]</span><span class="__shiki_dzsirb">-&gt;</span><span class="__shiki_140thh">(post:Post)</span></span>
