<span class="line"><span class="__shiki_1itgoe">WITH</span><span class="__shiki_140thh"> p, </span><span class="__shiki_dzsirb">collect</span><span class="__shiki_140thh">(friend) </span><span class="__shiki_1itgoe">as</span><span class="__shiki_140thh"> friends</span></span>
